<?php declare(strict_types=1);
require __DIR__.'/inventory-fields-environment.php';use Kulturhus\Verein\{Database,ClubChat};
$path=realpath($argv[1]??'');$prefix=realpath($inventoryTestRoot.'/.local/chat-ui-fixtures');if(!$path||!$prefix||!str_starts_with(str_replace('\\','/',$path),rtrim(str_replace('\\','/',$prefix),'/').'/'))throw new RuntimeException('Explicit private fixture required.');$f=json_decode(file_get_contents($path),true,16,JSON_THROW_ON_ERROR);if(!str_starts_with($f['club'],'chat-ui-'))throw new RuntimeException('Synthetic fixture only.');$db=\Kulturhus\Verein\Tests\MySqlFixture::existing($inventoryTestDatabase);
if(($argv[2]??'')==='peer-message'){(new ClubChat($db,$f['actors']['peer']))->send(($argv[3]??'')==='history'?$f['history']:$f['thread'],'Neue fiktive Nachricht während des Lesens.',bin2hex(random_bytes(16)));echo '{"ok":true}';exit;}
if(($argv[2]??'')!=='')throw new RuntimeException('Unknown test operation.');$db->exec('START TRANSACTION READ ONLY');$out=[];
foreach(['club_chats','club_chat_people','club_chat_messages'] as $table){$sql=$table==='club_chats'?'SELECT * FROM club_chats WHERE club_id=? ORDER BY id':($table==='club_chat_people'?'SELECT p.* FROM club_chat_people p JOIN club_chats c ON c.id=p.chat_id WHERE c.club_id=? ORDER BY p.chat_id,p.actor_id':'SELECT m.seq,m.chat_id,m.actor_id,m.body,m.request_key,m.file_name,m.file_mime,length(m.file_bytes) file_size FROM club_chat_messages m JOIN club_chats c ON c.id=m.chat_id WHERE c.club_id=? ORDER BY m.seq');$q=$db->prepare($sql);$q->execute([$f['club']]);$out[$table]=$q->fetchAll();}
